1	package docker
2	
3	import (
4		"encoding/base64"
5		"encoding/json"
6		"fmt"
7		"os"
8		"os/exec"
9		"path/filepath"
10		"sort"
11		"strconv"
12		"strings"
13	)
14	
15	// Container represents a Docker container with its metrics
16	type Container struct {
17		ID         string
18		Name       string
19		Image      string
20		State      string // running, exited, paused, created, restarting, dead
21		Status     string // "Up 2 hours", "Exited (0) 5min ago"
22		CreatedAt  string // "2 hours ago"
23		Ports      string
24		CPUPercent float64
25		MemUsage   string // "150MiB / 8GiB"
26		MemPercent float64
27		NetIO      string // "1.2kB / 3.4kB"
28		NetRX      int64  // received bytes (parsed from NetIO)
29		NetTX      int64  // transmitted bytes (parsed from NetIO)
30		BlockIO    string // "1.2MB / 3.4MB"
31		BlockRX    int64  // block bytes read (parsed from BlockIO)
32		BlockTX    int64  // block bytes written (parsed from BlockIO)
33	}
34	
35	// ListContainers returns a list of containers. If all is true, includes stopped containers.
36	func ListContainers(all bool) ([]Container, error) {
37		if _, err := exec.LookPath("docker"); err != nil {
38			return nil, fmt.Errorf("docker not found: %w", err)
39		}
40	
41		args := []string{"ps", "--format", "{{.ID}}\t{{.Names}}\t{{.Image}}\t{{.State}}\t{{.Status}}\t{{.CreatedAt}}\t{{.Ports}}"}
42		if all {
43			args = append(args[:1], append([]string{"--all"}, args[1:]...)...)
44		}
45	
46		cmd := exec.Command("docker", args...)
47		output, err := cmd.Output()
48		if err != nil {
49			return nil, fmt.Errorf("docker ps failed: %w", err)
50		}
51	
52		var containers []Container
53		for line := range strings.SplitSeq(strings.TrimSpace(string(output)), "\n") {
54			if line == "" {
55				continue
56			}
