283	// ListImages returns a list of local Docker images
284	func ListImages() ([]Image, error) {
285		if _, err := exec.LookPath("docker"); err != nil {
286			return nil, fmt.Errorf("docker not found: %w", err)
287		}
288	
289		// {{.Size}} from docker image ls gives disk usage (not content size)
290		cmd := exec.Command("docker", "image", "ls", "--format", "{{.ID}}\t{{.Repository}}\t{{.Tag}}\t{{.Size}}\t{{.CreatedAt}}")
291		output, err := cmd.Output()
292		if err != nil {
293			return nil, fmt.Errorf("docker image ls failed: %w", err)
294		}
295	
296		var images []Image
297		for line := range strings.SplitSeq(strings.TrimSpace(string(output)), "\n") {
298			if line == "" {
299				continue
300			}
301			parts := strings.SplitN(line, "\t", 5)
302			if len(parts) < 3 {
303				continue
304			}
305			img := Image{
306				ID:         parts[0],
307				Repository: parts[1],
308				Tag:        parts[2],
309			}
310			if len(parts) > 3 {
311				// docker image ls {{.Size}} = disk usage
312				img.UniqueSize = parseSize(parts[3])
313			}
314			if len(parts) > 4 {
315				img.CreatedAt = parts[4]
316			}
317			images = append(images, img)
318		}
319	
320		// Enrich with content size from docker image inspect and
321		// more precise disk usage from docker system df -v
322		enrichImagesWithDiskUsage(images)
323		enrichImagesWithContentSize(images)
324	
325		return images, nil
326	}
327	
328	// enrichImagesWithContentSize populates Size (content size) from docker image inspect.
329	// docker image inspect .Size gives the real content size (compressed layers in content store),
330	// while docker image ls .Size gives disk usage (unpacked layers on disk).
331	func enrichImagesWithContentSize(images []Image) {
332		if len(images) == 0 {
333			return
334		}
335	
336		// Collect all image IDs
337		ids := make([]string, 0, len(images))
338		for _, img := range images {
339			ids = append(ids, img.ID)
340		}
341	
342		// docker image inspect --format '{{.ID}} {{.Size}}' id1 id2 ...
343		args := append([]string{"image", "inspect", "--format", "{{.ID}}\t{{.Size}}"}, ids...)
344		cmd := exec.Command("docker", args...)
345		output, err := cmd.Output()
346		if err != nil {
347			return
348		}
349	
350		// Build lookup by short ID (strip "sha256:" prefix, keep first 12 chars)
351		lookup := make(map[string]int64)
352		for line := range strings.SplitSeq(strings.TrimSpace(string(output)), "\n") {
353			if line == "" {
354				continue
355			}
356			parts := strings.SplitN(line, "\t", 2)
357			if len(parts) < 2 {
358				continue
359			}
360			fullID := strings.TrimPrefix(parts[0], "sha256:")
361			shortID := fullID
362			if len(shortID) > 12 {
363				shortID = shortID[:12]
364			}
365			size, _ := strconv.ParseInt(parts[1], 10, 64)
366			lookup[shortID] = size
367		}
368	
369		for i := range images {
370			if size, ok := lookup[images[i].ID]; ok {
371				images[i].Size = size
372			}
373		}
374	}
375	
376	// enrichImagesWithDiskUsage populates UniqueSize and Containers from docker system df -v.
377	// Parses the raw text output because --format with -v does not expose per-image fields.
378	func enrichImagesWithDiskUsage(images []Image) {
379		cmd := exec.Command("docker", "system", "df", "-v")
380		output, err := cmd.Output()
381		if err != nil {
382			return
383		}
384	
385		type dfInfo struct {
386			UniqueSize int64
387			Containers int
388		}
389		lookup := make(map[string]dfInfo)
390	
391		lines := strings.Split(string(output), "\n")
392		inImages := false
393		// Column start positions derived from the header line
394		var tagPos, uniquePos, contPos int
395		headerFound := false
396	
397		for _, line := range lines {
398			trimmed := strings.TrimSpace(line)
399	
400			// Detect the Images section
401			if strings.HasPrefix(trimmed, "Images space usage:") {
402				inImages = true
403				continue
404			}
405			// End of Images section
406			if inImages && (strings.HasPrefix(trimmed, "Containers space usage:") ||
407				strings.HasPrefix(trimmed, "Local Volumes space usage:") ||
408				strings.HasPrefix(trimmed, "Build cache usage:")) {
409				break
410			}
411			if !inImages || trimmed == "" {
412				continue
413			}
414	
415			// Parse the header line to discover column positions
416			if strings.HasPrefix(trimmed, "REPOSITORY") {
417				tagPos = strings.Index(line, "TAG")
418				uniquePos = strings.Index(line, "UNIQUE SIZE")
419				contPos = strings.Index(line, "CONTAINERS")
420				headerFound = tagPos > 0 && uniquePos > 0 && contPos > 0
421				continue
422			}
423			if !headerFound {
424				continue
425			}
426	
427			// Extract fields using fixed column positions from the header
428			repo := strings.TrimSpace(safeSlice(line, 0, tagPos))
429			tag := strings.TrimSpace(safeSlice(line, tagPos, tagPos+20)) // TAG column is short
430			// Clean tag: take first word only (avoids bleeding into IMAGE ID)
431			if sp := strings.IndexByte(tag, ' '); sp > 0 {
432				tag = tag[:sp]
433			}
434			uniqueStr := strings.TrimSpace(safeSlice(line, uniquePos, contPos))
435			contStr := strings.TrimSpace(safeSlice(line, contPos, len(line)))
436			// Containers count is the first word of the remaining text
437			if sp := strings.IndexByte(contStr, ' '); sp > 0 {
438				contStr = contStr[:sp]
439			}
440	
441			if repo == "" || tag == "" {
442				continue
443			}
444	
445			key := repo + ":" + tag
446			containers, _ := strconv.Atoi(contStr)
447			lookup[key] = dfInfo{UniqueSize: parseSize(uniqueStr), Containers: containers}
448		}
449	
450		for i := range images {
451			key := images[i].Repository + ":" + images[i].Tag
452			if info, ok := lookup[key]; ok {
453				images[i].UniqueSize = info.UniqueSize
454				images[i].Containers = info.Containers
455			}
456		}
457	}
458	
459	// safeSlice returns s[start:end] clamped to valid bounds
460	func safeSlice(s string, start, end int) string {
461		if start < 0 {
462			start = 0
463		}
464		if start >= len(s) {
465			return ""
466		}
467		if end > len(s) {
468			end = len(s)
469		}
470		return s[start:end]
471	}
472	
473	// parseNetIO parses Docker NetIO string "1.2kB / 3.4kB" into received and transmitted bytes
474	func parseNetIO(netIO string) (rx, tx int64) {
475		parts := strings.SplitN(netIO, "/", 2)
476		if len(parts) != 2 {
477			return 0, 0
478		}
479		return parseSize(strings.TrimSpace(parts[0])), parseSize(strings.TrimSpace(parts[1]))
480	}
481	
482	// parseSize parses Docker human-readable sizes like "1.5GB", "256MB", "10.2kB" into bytes
483	func parseSize(s string) int64 {
484		s = strings.TrimSpace(s)
485		if s == "" {
486			return 0
487		}
488	
489		multipliers := []struct {
490			suffix string
491			mult   float64
492		}{
493			{"GB", 1e9},
494			{"MB", 1e6},
495			{"kB", 1e3},
496			{"B", 1},
497		}
498	
499		for _, m := range multipliers {
500			if numStr, ok := strings.CutSuffix(s, m.suffix); ok {
501				num, err := strconv.ParseFloat(numStr, 64)
502				if err != nil {
503					return 0
504				}
505				return int64(num * m.mult)
506			}
507		}
508		return 0
509	}
510	
511	// RemoveImage removes a Docker image by ID. If force is true, uses -f flag.
512	func RemoveImage(id string, force bool) error {
513		args := []string{"rmi", id}
514		if force {
515			args = []string{"rmi", "-f", id}
516		}
517		cmd := exec.Command("docker", args...)
518		if output, err := cmd.CombinedOutput(); err != nil {
519			return fmt.Errorf("docker rmi failed: %s", strings.TrimSpace(string(output)))
520		}
521		return nil
522	}
523	
524	// PruneImages removes all dangling (unused) images and returns the output
525	// PruneContainers removes all stopped containers
526	func PruneContainers() (string, error) {
527		cmd := exec.Command("docker", "container", "prune", "-f")
528		output, err := cmd.CombinedOutput()
529		if err != nil {
530			return "", fmt.Errorf("docker container prune failed: %s", strings.TrimSpace(string(output)))
531		}
532		return strings.TrimSpace(string(output)), nil
533	}
534	
535	func PruneImages() (string, error) {
536		cmd := exec.Command("docker", "image", "prune", "-f")
537		output, err := cmd.CombinedOutput()
538		if err != nil {
539			return "", fmt.Errorf("docker image prune failed: %s", strings.TrimSpace(string(output)))
540		}
541		return strings.TrimSpace(string(output)), nil
542	}
543	
