76	//     "tcp LISTEN 0 128 *:22 *:*\n\t\tusers:(("sshd",pid=1,fd=3))"
77	func parseSSOutput(raw string) []PortInfo {
78		var result []PortInfo
79		lines := strings.Split(raw, "\n")
80		for i := 0; i < len(lines); i++ {
81			line := strings.TrimSpace(lines[i])
82			if line == "" || strings.HasPrefix(line, "Netid") {
83				continue
84			}
85			fields := strings.Fields(line)
86			if len(fields) < 6 {
87				// Could be a continuation line with process info (starts with "users:(")
88				if len(result) > 0 && strings.HasPrefix(line, "users:(") {
89					result[len(result)-1].Process, result[len(result)-1].PID = parseSSProcess(line)
90				}
91				continue
92			}
93			pi := PortInfo{
94				Protocol:  fields[0],
95				State:     fields[1],
96				LocalAddr: fields[4],
97				PeerAddr:  fields[5],
98			}
99			if len(fields) >= 7 {
100				pi.Process, pi.PID = parseSSProcess(fields[6])
101			} else if i+1 < len(lines) {
102				// Check the next line for process info (newer iproute2 wraps to next line)
103				next := strings.TrimSpace(lines[i+1])
104				if strings.HasPrefix(next, "users:(") {
105					pi.Process, pi.PID = parseSSProcess(next)
106					i++ // consume the continuation line
107				}
108			}
109			result = append(result, pi)
110		}
111		return result
112	}
113	
114	// parseSSProcess extracts process name and PID from the ss process column.
115	// Input format: users:(("sshd",pid=1234,fd=3)) or users:(("a",pid=1,fd=2),("b",pid=3,fd=4))
116	func parseSSProcess(s string) (name, pid string) {
117		// Extract first process name: quoted string after `("`
118		if _, after, ok := strings.Cut(s, `("`); ok {
119			if name, _, ok = strings.Cut(after, `"`); !ok {
120				name = ""
121			}
122		}
123		// Extract first PID: digits after "pid="
124		if _, rest, ok := strings.Cut(s, "pid="); ok {
125			end := strings.IndexFunc(rest, func(r rune) bool {
126				return !unicode.IsDigit(r)
127			})
128			if end < 0 {
129				end = len(rest)
130			}
131			pid = rest[:end]
132		}
133		return
134	}

