package docker

import (
	"strings"
)

// RunIPAddr executes ip addr show in an ephemeral --network host container
// and returns the raw output as a DiagResult.
func RunIPAddr(image string) DiagResult {
	return runDiagHost(image, []string{"ip", "addr", "show"})
}

// RunIPRoute executes ip route show in an ephemeral --network host container
// and returns the raw output as a DiagResult.
func RunIPRoute(image string) DiagResult {
	return runDiagHost(image, []string{"ip", "route", "show"})
}

// RunIPLink executes ip -s link show to retrieve MTU and RX/TX error statistics
// per interface.
func RunIPLink(image string) DiagResult {
	return runDiagHost(image, []string{"ip", "-s", "link", "show"})
}

// RunIPNeigh executes ip neigh show to list ARP/neighbour cache entries.
func RunIPNeigh(image string) DiagResult {
	return runDiagHost(image, []string{"ip", "neigh", "show"})
}

// RunFirewallRules attempts to list firewall rules using iptables-legacy, iptables,
// or nft (in that order). The output is prefixed with "IPTABLES:" or "NFTABLES:" so
// the caller can select the appropriate parser. "UNAVAILABLE:" is returned when none
// of the tools are found in the image.
// Requires --privileged to access netfilter tables.
func RunFirewallRules(image string) DiagResult {
	if runner.LookPath() != nil {
		return DiagResult{false, "docker not found"}
	}
	shellCmd := `if command -v iptables-legacy >/dev/null 2>&1; then ` +
		`echo "IPTABLES:" && iptables-legacy -L -n --line-numbers; ` +
		`elif command -v iptables >/dev/null 2>&1; then ` +
		`echo "IPTABLES:" && iptables -L -n --line-numbers; ` +
		`elif command -v nft >/dev/null 2>&1; then ` +
		`echo "NFTABLES:" && nft list ruleset; ` +
		`else echo "UNAVAILABLE:"; fi`
	args := []string{
		"run", "--rm", "--network", "host", "--privileged",
		image, "/bin/sh", "-c", shellCmd,
	}
	output, err := dockerCombined(args...)
	out := strings.ReplaceAll(string(output), "\r\n", "\n")
	out = strings.ReplaceAll(out, "\r", "\n")
	out = strings.TrimSpace(out)
	return DiagResult{err == nil && !strings.HasPrefix(out, "UNAVAILABLE:"), out}
}

package docker

import "strings"

// Volume represents a Docker volume
type Volume struct {
	Name       string
	Driver     string
	Mountpoint string
	Created    string
}

// ListVolumes returns a list of Docker volumes
func ListVolumes() ([]Volume, error) {
	if err := requireDocker(); err != nil {
		return nil, err
	}
	output, err := dockerOutput("volume", "ls", "--format", "{{.Name}}\t{{.Driver}}\t{{.Mountpoint}}")
	if err != nil {
		return nil, wrapErr("docker volume ls", err)
	}

	var volumes []Volume
	for _, line := range splitLines(output) {
		parts := strings.SplitN(line, "\t", 3)
		if len(parts) < 2 {
			continue
		}
		v := Volume{Name: parts[0], Driver: parts[1]}
		if len(parts) > 2 {
			v.Mountpoint = parts[2]
		}
		volumes = append(volumes, v)
	}
	return volumes, nil
}

// CreateVolume creates a Docker volume with the given name and optional driver
func CreateVolume(name, driver string) error {
	args := []string{"volume", "create"}
	if driver != "" {
		args = append(args, "--driver", driver)
	}
	args = append(args, name)
	return mutate("docker volume create", args...)
}

// RemoveVolume removes a Docker volume by name
func RemoveVolume(name string) error {
	return mutate("docker volume rm", "volume", "rm", name)
}

// PruneVolumes removes all unused Docker volumes
func PruneVolumes() (string, error) {
	return prune("docker volume prune", "volume", "prune", "-f")
}

package docker

import (
	"slices"
	"testing"
)

func TestListVolumesParsesOutput(t *testing.T) {
	stubOutput(t, "volume",
		"pgdata\tlocal\t/var/lib/docker/volumes/pgdata/_data\n"+
			"cache\tlocal\n")

	got, err := ListVolumes()

	if err != nil {
		t.Fatalf("ListVolumes() error = %v", err)
	}
	if len(got) != 2 {
		t.Fatalf("ListVolumes() returned %d volumes, want 2", len(got))
	}
	want := Volume{Name: "pgdata", Driver: "local", Mountpoint: "/var/lib/docker/volumes/pgdata/_data"}
	if got[0] != want {
		t.Errorf("first volume = %+v, want %+v", got[0], want)
	}
	// A missing mountpoint must not drop the row.
	if got[1].Name != "cache" || got[1].Mountpoint != "" {
		t.Errorf("second volume = %+v, want cache with no mountpoint", got[1])
	}
}

func TestCreateVolumeOmitsEmptyDriver(t *testing.T) {
	tests := []struct {
		name     string
		driver   string
		wantArgs []string
	}{
		{"with driver", "local", []string{"volume", "create", "--driver", "local", "data"}},
		{"without driver lets docker choose", "", []string{"volume", "create", "data"}},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			s := stub(t, &stubRunner{})

			if err := CreateVolume("data", tt.driver); err != nil {
				t.Fatalf("CreateVolume() error = %v", err)
			}
			if !slices.Equal(s.lastArgs(), tt.wantArgs) {
				t.Errorf("args = %v, want %v", s.lastArgs(), tt.wantArgs)
			}
		})
	}
}

func TestRemoveVolume(t *testing.T) {
	s := stub(t, &stubRunner{})

	if err := RemoveVolume("data"); err != nil {
		t.Fatalf("RemoveVolume() error = %v", err)
	}
	if want := []string{"volume", "rm", "data"}; !slices.Equal(s.lastArgs(), want) {
		t.Errorf("args = %v, want %v", s.lastArgs(), want)
	}
}

package docker

import (
	"encoding/base64"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
)

// dockerHubKeys lists all keys Docker uses for Docker Hub in ~/.docker/config.json.
// `docker login docker.io` stores credentials under "https://index.docker.io/v1/".
var dockerHubKeys = []string{
	"docker.io",
	"registry-1.docker.io",
	"https://index.docker.io/v1/",
	"https://index.docker.io/v1",
	"https://registry-1.docker.io",
}

// registryCandidates returns all URL variants to look up in ~/.docker/config.json.
func registryCandidates(registryURL string) []string {
	base := strings.TrimSuffix(registryURL, "/")

	// Check if this URL is any known Docker Hub alias; if so, return the full set.
	for _, alias := range dockerHubKeys {
		if strings.EqualFold(base, strings.TrimSuffix(alias, "/")) {
			return dockerHubKeys
		}
	}

	// Generic: bare hostname, https://, http:// variants.
	candidates := []string{base}
	if strings.HasPrefix(base, "https://") {
		candidates = append(candidates, strings.TrimPrefix(base, "https://"))
	} else if strings.HasPrefix(base, "http://") {
		candidates = append(candidates, strings.TrimPrefix(base, "http://"))
	} else {
		candidates = append(candidates, "https://"+base, "http://"+base)
	}
	return candidates
}

// dockerConfigPath returns the path to ~/.docker/config.json.
func dockerConfigPath() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".docker", "config.json"), nil
}

// readDockerConfig reads and unmarshals ~/.docker/config.json into v.
func readDockerConfig(v any) error {
	path, err := dockerConfigPath()
	if err != nil {
		return err
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	return json.Unmarshal(data, v)
}

// RegistryLogin authenticates with a Docker/OCI registry using `docker login`.
// The password is passed via stdin to avoid exposing it in the process list.
func RegistryLogin(registryURL, username, password string) error {
	if err := requireDocker(); err != nil {
		return err
	}
	output, err := runner.Run(dockerCmd{
		Args:     []string{"login", registryURL, "-u", username, "--password-stdin"},
		Stdin:    password,
		Combined: true,
	})
	if err != nil {
		return errWithOutput("docker login", output)
	}
	return nil
}

// IsRegistryLoggedIn reports whether stored credentials exist for registryURL
// by inspecting ~/.docker/config.json.
func IsRegistryLoggedIn(registryURL string) bool {
	var cfg struct {
		Auths map[string]json.RawMessage `json:"auths"`
	}
	if err := readDockerConfig(&cfg); err != nil {
		return false
	}
	for _, c := range registryCandidates(registryURL) {
		if _, ok := cfg.Auths[c]; ok {
			return true
		}
	}
	return false
}

// RegistryLogout removes stored credentials for a Docker/OCI registry.
// It runs `docker logout` (cleans system credential stores) then directly
// removes all matching keys from ~/.docker/config.json to handle cases where
// docker logout leaves behind alias entries (e.g. docker.io vs https://index.docker.io/v1/).
func RegistryLogout(registryURL string) error {
	if err := requireDocker(); err != nil {
		return err
	}
	if err := mutate("docker logout", "logout", registryURL); err != nil {
		return err
	}
	// Also remove all matching alias keys directly from config.json.
	_ = removeFromDockerConfig(registryURL)
	return nil
}

// removeFromDockerConfig removes all URL variants of registryURL from the auths
// section of ~/.docker/config.json. Errors are non-fatal (best effort).
func removeFromDockerConfig(registryURL string) error {
	configPath, err := dockerConfigPath()
	if err != nil {
		return err
	}

	var raw map[string]json.RawMessage
	if err := readDockerConfig(&raw); err != nil {
		return err
	}
	authsRaw, ok := raw["auths"]
	if !ok {
		return nil
	}
	var auths map[string]json.RawMessage
	if err := json.Unmarshal(authsRaw, &auths); err != nil {
		return err
	}

	changed := false
	for _, candidate := range registryCandidates(registryURL) {
		if _, exists := auths[candidate]; exists {
			delete(auths, candidate)
			changed = true
		}
	}
	if !changed {
		return nil
	}

	updated, err := json.Marshal(auths)
	if err != nil {
		return err
	}
	raw["auths"] = updated
	out, err := json.MarshalIndent(raw, "", "\t")
	if err != nil {
		return err
	}
	return os.WriteFile(configPath, out, 0600)
}

// GetStoredCreds retrieves Docker credentials for registryURL from
// ~/.docker/config.json. It tries the per-registry credential helper
// (credHelpers), then the global credsStore, and finally falls back to the
// inline base64-encoded auth field. Returns ok=false when no credentials are
// found.
func GetStoredCreds(registryURL string) (username, password string, ok bool) {
	var cfg struct {
		Auths map[string]struct {
			Auth string `json:"auth"`
		} `json:"auths"`
		CredsStore  string            `json:"credsStore"`
		CredHelpers map[string]string `json:"credHelpers"`
	}
	if err := readDockerConfig(&cfg); err != nil {
		return "", "", false
	}

	// Normalise the URL to a bare hostname for helper lookups.
	hostname := strings.TrimSuffix(registryURL, "/")
	for _, prefix := range []string{"https://", "http://"} {
		hostname = strings.TrimPrefix(hostname, prefix)
	}

	helper := cfg.CredHelpers[hostname]
	if helper == "" {
		helper = cfg.CredsStore
	}
	if helper != "" {
		if u, p, ok := getCredsFromHelper(helper, hostname); ok {
			return u, p, true
		}
	}

	for _, candidate := range registryCandidates(registryURL) {
		if entry, ok := cfg.Auths[candidate]; ok && entry.Auth != "" {
			if u, p, ok := decodeAuth(entry.Auth); ok {
				return u, p, true
			}
		}
	}
	return "", "", false
}

// decodeAuth splits a base64 "username:password" auth field.
func decodeAuth(auth string) (username, password string, ok bool) {
	decoded, err := base64.StdEncoding.DecodeString(auth)
	if err != nil {
		return "", "", false
	}
	if idx := strings.IndexByte(string(decoded), ':'); idx >= 0 {
		return string(decoded[:idx]), string(decoded[idx+1:]), true
	}
	return "", "", false
}

// getCredsFromHelper calls `docker-credential-<helper> get` and parses the JSON response.
func getCredsFromHelper(helper, serverURL string) (username, password string, ok bool) {
	out, err := runner.Run(dockerCmd{
		Args:   []string{"get"},
		Stdin:  serverURL,
		Helper: helper,
	})
	if err != nil {
		return "", "", false
	}
	var result struct {
		Username string `json:"Username"`
		Secret   string `json:"Secret"`
	}
	if err := json.Unmarshal(out, &result); err != nil {
		return "", "", false
	}
	if result.Secret == "" {
		return "", "", false
	}
	return result.Username, result.Secret, true
}

// RegistryAlias pairs a URL prefix with a short alias for display purposes.
type RegistryAlias struct {
	URL   string
	Alias string
}

// ApplyAliases replaces registry URL prefixes in an image name with their configured alias.
// Example: URL="gitlab.com/my-group", Alias="gl" turns
// "gitlab.com/my-group/my-image:1.0" into "gl/my-image:1.0".
func ApplyAliases(imageName string, aliases []RegistryAlias) string {
	for _, a := range aliases {
		if a.Alias == "" || a.URL == "" {
			continue
		}
		prefix := strings.TrimSuffix(a.URL, "/") + "/"
		if strings.HasPrefix(imageName, prefix) {
			return a.Alias + "/" + strings.TrimPrefix(imageName, prefix)
		}
	}
	return imageName
}

package docker

import (
	"strconv"
	"strings"
)

// OCIStats contains OCI resource counts and disk usage
type OCIStats struct {
	Available       bool
	ImagesCount     int
	ImagesSize      string
	ContainersCount int
	ContainersSize  string
	VolumesCount    int
	VolumesSize     string
}

// FetchOCIStats returns OCI resource counts and disk usage via docker system df
func FetchOCIStats() OCIStats {
	stats := OCIStats{}

	if runner.LookPath() != nil {
		return stats
	}

	output, err := dockerOutput("system", "df", "--format", "{{.Type}}\t{{.TotalCount}}\t{{.Size}}")
	if err != nil {
		return stats
	}

	stats.Available = true

	for _, line := range splitLines(output) {
		parts := strings.SplitN(line, "\t", 3)
		if len(parts) < 3 {
			continue
		}
		count, _ := strconv.Atoi(parts[1])
		size := parts[2]

		switch parts[0] {
		case "Images":
			stats.ImagesCount = count
			stats.ImagesSize = size
		case "Containers":
			stats.ContainersCount = count
			stats.ContainersSize = size
		case "Local Volumes":
			stats.VolumesCount = count
			stats.VolumesSize = size
		}
	}

	return stats
}

package gitlab

import (
	"os"
	"os/exec"
)

// Clone clones a Git repository to the target path
// repoURL is the full URL to clone (HTTPS or SSH)
// targetPath is the absolute path where the repo should be cloned
func Clone(repoURL, targetPath string) error {
	cmd := exec.Command("git", "clone", repoURL, targetPath)
	cmd.Stdout = nil
	cmd.Stderr = nil
	return cmd.Run()
}

// DirExists checks if a directory exists at the given path
func DirExists(path string) bool {
	info, err := os.Stat(path)
	if err != nil {
		return false
	}
	return info.IsDir()
}

