	"net/http/httptest"
	"testing"
	"time"
)

func TestProbePaths(t *testing.T) {
	var hits []string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hits = append(hits, r.Method+" "+r.URL.Path+" auth="+r.Header.Get("PRIVATE-TOKEN"))
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("X-Total", "42")
		_, _ = w.Write([]byte(`{"id":1,"username":"alice"}`))
	}))
	defer srv.Close()

	c, err := NewClient(srv.URL, "tok")
	if err != nil {
		t.Fatal(err)
	}
	u, err := TestConnection(c)
	t.Logf("user=%+v err=%v", u, err)

	srv2 := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusUnauthorized)
		_, _ = w.Write([]byte(`{"message":"401 Unauthorized"}`))
	}))
	defer srv2.Close()
	c2, _ := NewClient(srv2.URL, "bad")
	start := time.Now()
	_, err = TestConnection(c2)
	t.Logf("401 err=%v elapsed=%v", err, time.Since(start))

	t.Logf("hits=%v", hits)
}

